+				      struct scatterlist *src,
+				      unsigned int cryptlen,
+				      u8 iv[AES_BLOCK_SIZE],
+				      const struct aes_key *key)
+{
+	AES_CRYPT_SG(aes_cbc_encrypt, dst, src, cryptlen, 0, iv, key);
